## 2. GraphQL API Design

### 2.1 Schema Design

```graphql
# schema.graphql

scalar DateTime
scalar JSON
scalar UUID

enum UserRole {
  ADMIN
  ENGINEER
  MANAGER
  VIEWER
}

enum OrderStatus {
  PENDING
  PROCESSING
  SHIPPED
  DELIVERED
  CANCELLED
}

type User {
  id: ID!
  email: String!
  name: String!
  role: UserRole!

  # Relations
  manager: User
  directReports: [User!]!
  orders: OrderConnection!

  # Computed
  fullName: String!
  isActive: Boolean!

  # Timestamps
  createdAt: DateTime!
  updatedAt: DateTime!

  # Meta
  metadata: JSON
}

type Order {
  id: ID!
  status: OrderStatus!
  total: Decimal!
  currency: String!

  # Relations
  user: User!
  items: [OrderItem!]!

  # Timestamps
  createdAt: DateTime!
  updatedAt: DateTime!
}

type OrderItem {
  id: ID!
  quantity: Int!
  unitPrice: Decimal!
  totalPrice: Decimal!
  product: Product!
}

type Product {
  id: ID!
  name: String!
  description: String
  price: Decimal!
  inStock: Boolean!
  category: Category!
}

type Category {
  id: ID!
  name: String!
  slug: String!
  parent: Category
  children: [Category!]!
  products: ProductConnection!
}

# Pagination
type UserConnection {
  edges: [UserEdge!]!
  pageInfo: PageInfo!
  totalCount: Int!
}

type UserEdge {
  node: User!
  cursor: String!
}

type PageInfo {
  hasNextPage: Boolean!
  hasPreviousPage: Boolean!
  startCursor: String
  endCursor: String
}

# Input types
input CreateUserInput {
  email: String!
  name: String!
  role: UserRole = VIEWER
  metadata: JSON
}

input UpdateUserInput {
  email: String
  name: String
  role: UserRole
  metadata: JSON
}

input UserFilterInput {
  role: UserRole
  search: String
  createdAfter: DateTime
  createdBefore: DateTime
}

input OrderByInput {
  field: OrderSortField!
  direction: SortDirection = ASC
}

enum OrderSortField {
  CREATED_AT
  UPDATED_AT
  TOTAL
}

enum SortDirection {
  ASC
  DESC
}
```

### 2.2 Complete Query/Mutation Examples

