## 4. Ansible Playbooks

### 4.1 Kubernetes Node Configuration Playbook

```yaml
# ansible/playbooks/kubernetes-nodes.yml
---
- name: Configure Kubernetes Nodes
  hosts: k8s_nodes
  become: true
  gather_facts: true
  vars:
    k8s_version: "1.28.0"
    container_runtime: containerd
    pod_cidr: "10.244.0.0/16"
    service_cidr: "10.96.0.0/12"

  pre_tasks:
    - name: Update apt cache
      ansible.builtin.apt:
        update_cache: yes
        cache_valid_time: 3600
      when: ansible_os_family == "Debian"

    - name: Create kubernetes repo directory
      ansible.builtin.file:
        path: /etc/apt/keyrings
        state: directory
        mode: '0755'

  tasks:
    - name: Install prerequisites
      ansible.builtin.apt:
        name:
          - apt-transport-https
          - ca-certificates
          - curl
          - gnupg
          - lsb-release
          - software-properties-common
        state: present
        update_cache: yes

    - name: Add Kubernetes signing key
      ansible.builtin.apt_key:
        url: https://pkgs.k8s.io/core:/stable:/v1.28/deb/Release.key
        state: present

    - name: Add Kubernetes repository
      ansible.builtin.apt_repository:
        repo: "deb [signed-by=/etc/apt/keyrings/kubernetes-apt-keyring.gpg] https://pkgs.k8s.io/core:/stable:/v1.28/deb/ /"
        state: present

    - name: Install containerd
      ansible.builtin.apt:
        name:
          - containerd
        state: present
        update_cache: yes

    - name: Generate containerd config
      ansible.builtin.command:
        cmd: containerd config default
      register: containerd_config

    - name: Save containerd config
      ansible.builtin.copy:
        content: "{{ containerd_config.stdout }}"
        dest: /etc/containerd/config.toml
        mode: '0644'

    - name: Configure containerd systemd
      ansible.builtin.lineinfile:
        path: /etc/containerd/config.toml
        regexp: '^\s*SystemdCgroup\s*='
        line: '            SystemdCgroup = true'

    - name: Restart containerd
      ansible.builtin.service:
        name: containerd
        state: restarted
        enabled: yes

    - name: Install Kubernetes components
      ansible.builtin.apt:
        name:
          - kubelet
          - kubeadm
          - kubectl
        state: present
        default_release: v1.28

    - name: Hold Kubernetes packages
      community.general.debconf:
        name: "{{ item }}"
        question: "{{ item }}/hold"
        value: "true"
        vtype: boolean
      loop:
        - kubelet
        - kubeadm
        - kubectl

    - name: Configure kernel modules
      community.general.modprobe:
        name: "{{ item }}"
        state: present
      loop:
        - overlay
        - br_netfilter

    - name: Configure sysctl
      ansible.posix.sysctl:
        name: "{{ item.name }}"
        value: "{{ item.value }}"
        sysctl_file: /etc/sysctl.d/k8s.conf
        state: present
        reload: yes
      loop:
        - { name: net.bridge.bridge-nf-call-iptables, value: 1 }
        - { name: net.bridge.bridge-nf-call-ip6tables, value: 1 }
        - { name: net.ipv4.ip_forward, value: 1 }
        - { name: ip_tables, value: 1 }
        - { name: i6_tables, value: 1 }
        - { name: ip_vs, value: 1 }
        - { name: ip_vs_rr, value: 1 }
        - { name: ip_vs_wrr, value: 1 }
        - { name: ip_vs_sh, value: 1 }
        - { name: nf_conntrack, value: 1 }

    - name: Disable swap
      ansible.builtin.shell: |
        swapoff -a && sed -i '/swap/d' /etc/fstab
      when: ansible_swaptotal_mb > 0

    - name: Ensure kubelet is running
      ansible.builtin.service:
        name: kubelet
        state: started
        enabled: yes

  handlers:
    - name: Reload systemd
      ansible.builtin.systemd_service:
        daemon_reload: yes

    - name: Restart kubelet
      ansible.builtin.service:
        name: kubelet
