    schemaname,
    tablename,
    seq_scan - idx_scan AS missing_index_scans,
    idx_scan AS index_scans
FROM pg_stat_user_tables
WHERE seq_scan - idx_scan > 100
ORDER BY missing_index_scans DESC;

