        name: cpu
        target:
          type: Utilization
          averageUtilization: 70

    # Memory metric
    - type: Resource
      resource:
        name: memory
        target:
          type: Utilization
          averageUtilization: 80

    # Custom Prometheus metric - HTTP request rate
    - type: Pods
      pods:
        metric:
          name: http_requests_total
          selector:
            matchLabels:
              app: api
        target:
          type: AverageValue
          averageValue: "500"

    # Custom Prometheus metric - Error rate
    - type: Pods
      pods:
        metric:
          name: http_requests_errors_total
          selector:
            matchLabels:
              app: api
        target:
          type: AverageValue
          averageValue: "10"

    # Queue depth from Redis
    - type: External
      external:
        metric:
          name: redis_connected_clients
          selector:
            matchLabels:
              role: queue
        target:
          type: AverageValue
          averageValue: "1000"

  behavior:
    scaleDown:
      # 5 minute stabilization window
      stabilizationWindowSeconds: 300
      policies:
        # No more than 10% scale down per minute
        - type: Percent
          value: 10
          periodSeconds: 60
        # No more than 2 pods per minute
        - type: Pods
          value: 2
          periodSeconds: 60
      selectPolicy: Min

    scaleUp:
      # Immediate scale up (no stabilization)
      stabilizationWindowSeconds: 0
      policies:
        # Can double (100%) pods every 15 seconds
        - type: Percent
          value: 100
          periodSeconds: 15
        # Can add 4 pods every 15 seconds
        - type: Pods
          value: 4
          periodSeconds: 15
      selectPolicy: Max

